window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f7e172fd8dcf19b0"]={"versions": [{"id": "FIG-f7e172fd8dcf19b0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation eines Einzelschritts innerhalb der Funktion <code>E2E_P07mProtect()</code> des AUTOSAR E2E-Profils 7m (E2E-Protokollbibliothek). Das Diagramm beschreibt den Kontroll- und Manipulationsfluss zur Serialisierung des Feldes MessageResult in ein Datenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Aktivität / Scope: <code>E2E_P07mProtect()</code> (gekennzeichnet über die Kopf-/Referenzmarke).</li>\n<li>Startknoten (Initial Node): Schwarzer Vollkreis.</li>\n<li>Endknoten (Activity Final Node): Umrandeter Kreis mit zentriertem Punkt.</li>\n<li>Aktion (Action Node): <code>Copy 2-bit MessageResult to the bits 2 and 3 of byte Data[Offset +20] in Big Endian order, i.e., Data[Offset+20] = (Data[Offset+20] &amp; 0xCF) | ((messageType &amp; 0x03) &lt;&lt; 4)</code>.</li>\n<li>Daten- und Schnittstellenelemente: Byte-Array <code>Data[]</code>, Konfigurations-/Positionsvariable <code>Offset</code>, 2-Bit-Eingabewert <code>MessageResult</code> (in der Formel fälschlicherweise als <code>messageType</code> bezeichnet).</li>\n<li>Steuerflüsse (Control Flows): Gerichtete Kanten vom Initialknoten zur Aktion und von der Aktion zum Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn der Teilaktivität am Initialknoten beim Aufruf des Teilschritts „Write Message Result“.</li>\n<li>Ausführung der Bitmanipulation an Byte <code>Data[Offset + 20]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Maskierung der Bits 2 und 3 des bestehenden Bytes mittels bitweisem UND mit <code>0xCF</code> (Binär <code>1100 1111</code>).</li>\n<li>Einblenden des 2-Bit-Werts (auf 2 Bit maskiert und um 4 Bits nach links verschoben, um die Bitpositionen 4 und 5 zu belegen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Weiterleiten des Kontrollflusses zum Aktivitätsendknoten und Beendigung des Einzelschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Darstellung definiert normativ das Verhalten der Anforderung [PRS_E2E_00807] für das Schutzprofil 7m.</li>\n<li>Implementierer müssen beachten, dass Text und Formel in der Aktionsbeschreibung zwei Diskrepanzen aufweisen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die textuelle Beschreibung verlangt die Belegung der Bits 2 und 3, die explizite Bitmaske <code>0xCF</code> (<code>1100 1111_b</code>) sowie die Linksverschiebung <code>&lt;&lt; 4</code> adressieren jedoch die Bits 4 und 5 des Bytes <code>Data[Offset + 20]</code>.</li>\n<li>Im Formelausdruck wird die Variable <code>messageType</code> statt <code>MessageResult</code> referenziert. Bei der Code-Generierung bzw. Protokollimplementierung ist sicherzustellen, dass der tatsächliche Parameter <code>MessageResult</code> verwendet wird und das Bit-Layout konsistent mit der Gesamtrahmen-Definition von Profil 7m abgeglichen wird.</li>\n</ol>"}, {"id": "FIG-539f7896f4ca03eb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation eines Einzelschritts innerhalb der Funktion <code>E2E_P07mProtect()</code> des AUTOSAR E2E-Profils 7m (E2E-Protokollbibliothek). Das Diagramm beschreibt den Kontroll- und Manipulationsfluss zur Serialisierung des Feldes MessageResult in ein Datenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Aktivität / Scope: <code>E2E_P07mProtect()</code> (gekennzeichnet über die Kopf-/Referenzmarke).</li>\n<li>Startknoten (Initial Node): Schwarzer Vollkreis.</li>\n<li>Endknoten (Activity Final Node): Umrandeter Kreis mit zentriertem Punkt.</li>\n<li>Aktion (Action Node): <code>Copy 2-bit MessageResult to the bits 2 and 3 of byte Data[Offset +20] in Big Endian order, i.e., Data[Offset+20] = (Data[Offset+20] &amp; 0xCF) | ((messageType &amp; 0x03) &lt;&lt; 4)</code>.</li>\n<li>Daten- und Schnittstellenelemente: Byte-Array <code>Data[]</code>, Konfigurations-/Positionsvariable <code>Offset</code>, 2-Bit-Eingabewert <code>MessageResult</code> (in der Formel fälschlicherweise als <code>messageType</code> bezeichnet).</li>\n<li>Steuerflüsse (Control Flows): Gerichtete Kanten vom Initialknoten zur Aktion und von der Aktion zum Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn der Teilaktivität am Initialknoten beim Aufruf des Teilschritts „Write Message Result“.</li>\n<li>Ausführung der Bitmanipulation an Byte <code>Data[Offset + 20]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Maskierung der Bits 2 und 3 des bestehenden Bytes mittels bitweisem UND mit <code>0xCF</code> (Binär <code>1100 1111</code>).</li>\n<li>Einblenden des 2-Bit-Werts (auf 2 Bit maskiert und um 4 Bits nach links verschoben, um die Bitpositionen 4 und 5 zu belegen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Weiterleiten des Kontrollflusses zum Aktivitätsendknoten und Beendigung des Einzelschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Darstellung definiert normativ das Verhalten der Anforderung [PRS_E2E_00807] für das Schutzprofil 7m.</li>\n<li>Implementierer müssen beachten, dass Text und Formel in der Aktionsbeschreibung zwei Diskrepanzen aufweisen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die textuelle Beschreibung verlangt die Belegung der Bits 2 und 3, die explizite Bitmaske <code>0xCF</code> (<code>1100 1111_b</code>) sowie die Linksverschiebung <code>&lt;&lt; 4</code> adressieren jedoch die Bits 4 und 5 des Bytes <code>Data[Offset + 20]</code>.</li>\n<li>Im Formelausdruck wird die Variable <code>messageType</code> statt <code>MessageResult</code> referenziert. Bei der Code-Generierung bzw. Protokollimplementierung ist sicherzustellen, dass der tatsächliche Parameter <code>MessageResult</code> verwendet wird und das Bit-Layout konsistent mit der Gesamtrahmen-Definition von Profil 7m abgeglichen wird.</li>\n</ol>"}], "trans": [{"from": "FIG-f7e172fd8dcf19b0", "to": "FIG-539f7896f4ca03eb", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
